// 使模拟窑温、釉色和开片纹理同步变化。
import{updateProgress}from'./common.js';
const input=document.querySelector('#kiln-temperature'),image=document.querySelector('#kiln-art>img'),cracks=document.querySelector('.kiln-cracks path');function update(){const temperature=Number(input.value),t=(temperature-1100)/200;document.querySelector('#temperature-output').textContent=temperature+'℃';const name=t<.28?'灰青':t<.67?'粉青':'梅子青';const note=t<.28?'灰青 · 像一场雨之前，尚未亮起的天。':t<.67?'粉青 · 光泽温和，似一片含蓄的玉。':'梅子青 · 青色渐深，光泽沉入釉层。';image.style.filter=`saturate(${.25+t*.9}) brightness(${1.3-t*.52}) hue-rotate(${t*12}deg)`;cracks.style.strokeDashoffset=String(1000-t*800);cracks.style.opacity=String(t*.7);document.querySelector('#kiln-glaze').textContent=name;document.querySelector('#kiln-note').textContent=note;updateProgress(t*100,`${temperature}℃ · ${name}（艺术示意）`);}input.addEventListener('input',update);document.querySelector('#reset-craft').addEventListener('click',()=>{input.value='1200';update();});update();
